-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the petrophysics capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: some graded figure(s) printed; section 3 pick A (re-case)
-- advanced: every graded figure(s) printed; section 3 pick A (re-case)
--
-- THE LABEL:
--   Open book, in part: some of the figures this capstone grades can be read in
--   this tier's lessons or on a panel as it opens, so for now those check that
--   you can find, read and report them correctly. A later update moves it to a
--   case of its own.
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- petrophysics / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'petrophysics' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book petrophysics refused: petrophysics/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '351d515e6082352115c8fb8aa199485d' and fields = '[{"key": "sand_a_net_m", "tol": 0.75, "unit": "m", "label": "SAND_A net pay", "expected": 18.0}, {"key": "sand_a_phi_avg", "tol": 0.01, "unit": "v/v", "label": "SAND_A average porosity", "expected": 0.20805198865869562}, {"key": "sand_a_sw_avg", "tol": 0.02, "unit": "v/v", "label": "SAND_A average Sw", "expected": 0.361262643786335}, {"key": "sand_b_net_m", "tol": 0.75, "unit": "m", "label": "SAND_B net pay", "expected": 5.5}, {"key": "sand_b_phi_avg", "tol": 0.01, "unit": "v/v", "label": "SAND_B average porosity", "expected": 0.1417010751338701}, {"key": "sand_b_sw_avg", "tol": 0.02, "unit": "v/v", "label": "SAND_B average Sw", "expected": 0.5423153983883204}]'::jsonb then 'old'
              when md5(prompt) = '8b87ccc9c4917dec18964452eac31cc2' and fields = '[{"key": "sand_a_net_m", "tol": 0.75, "unit": "m", "label": "SAND_A net pay", "expected": 18.0}, {"key": "sand_a_phi_avg", "tol": 0.01, "unit": "v/v", "label": "SAND_A average porosity", "expected": 0.20805198865869562}, {"key": "sand_a_sw_avg", "tol": 0.02, "unit": "v/v", "label": "SAND_A average Sw", "expected": 0.361262643786335}, {"key": "sand_b_net_m", "tol": 0.75, "unit": "m", "label": "SAND_B net pay", "expected": 5.5}, {"key": "sand_b_phi_avg", "tol": 0.01, "unit": "v/v", "label": "SAND_B average porosity", "expected": 0.1417010751338701}, {"key": "sand_b_sw_avg", "tol": 0.02, "unit": "v/v", "label": "SAND_B average Sw", "expected": 0.5423153983883204}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'petrophysics' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book petrophysics refused: petrophysics/beginner matches neither its published form (prompt md5 351d515e6082352115c8fb8aa199485d) nor its W1 form (prompt md5 8b87ccc9c4917dec18964452eac31cc2), with the fields this file was generated against';
  end if;

  -- petrophysics / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'petrophysics' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book petrophysics refused: petrophysics/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '23f7efbf38f104a86d05616a8f4a1355' and fields = '[{"key": "phind_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean neutron-density porosity", "expected": 0.17615030026601647}, {"key": "phiw_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean Wyllie sonic porosity", "expected": 0.2069057569286416}, {"key": "pickett_a_rw_2072_2078", "tol": 0.002, "unit": "Ω·m", "label": "Pickett fit over 2072 to 2078 m: a·Rw", "expected": 0.6886854786769905}, {"key": "pickett_m_2072_2078", "tol": 0.0002, "unit": "-", "label": "Pickett fit over 2072 to 2078 m: cementation exponent m", "expected": 0.8784525453945112}, {"key": "sw_sim_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Simandoux)", "expected": 0.43350268917150697}, {"key": "sw_ind_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Indonesia)", "expected": 0.4280109754526606}]'::jsonb then 'old'
              when md5(prompt) = '4fc93836432a158c77906d14bf752067' and fields = '[{"key": "phind_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean neutron-density porosity", "expected": 0.17615030026601647}, {"key": "phiw_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean Wyllie sonic porosity", "expected": 0.2069057569286416}, {"key": "pickett_a_rw_2072_2078", "tol": 0.002, "unit": "Ω·m", "label": "Pickett fit over 2072 to 2078 m: a·Rw", "expected": 0.6886854786769905}, {"key": "pickett_m_2072_2078", "tol": 0.0002, "unit": "-", "label": "Pickett fit over 2072 to 2078 m: cementation exponent m", "expected": 0.8784525453945112}, {"key": "sw_sim_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Simandoux)", "expected": 0.43350268917150697}, {"key": "sw_ind_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Indonesia)", "expected": 0.4280109754526606}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'petrophysics' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book petrophysics refused: petrophysics/intermediate matches neither its published form (prompt md5 23f7efbf38f104a86d05616a8f4a1355) nor its W1 form (prompt md5 4fc93836432a158c77906d14bf752067), with the fields this file was generated against';
  end if;

  -- petrophysics / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'petrophysics' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book petrophysics refused: petrophysics/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'fc73fb0f8363d2b7cec10185793978da' and fields = '[{"key": "rw_arps", "tol": 5e-05, "unit": "ohm.m", "label": "Sample Rw at formation temperature (Arps)", "expected": 0.049910478128179045}, {"key": "rwe_ssp", "tol": 5e-05, "unit": "ohm.m", "label": "Rwe from the SP quicklook", "expected": 0.049831180824251246}, {"key": "sw_waterleg_mean", "tol": 0.0005, "unit": "v/v", "label": "Water-leg mean Sw with the Arps Rw", "expected": 0.9991043802143901}, {"key": "sand_a_net_arps", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the Arps Rw", "expected": 18}, {"key": "sand_a_sw_avg_arps", "tol": 0.005, "unit": "v/v", "label": "SAND_A pay-average Sw with the Arps Rw", "expected": 0.3609390898147585}, {"key": "sand_a_net_uncorrected", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the raw sample Rw", "expected": 16.5}]'::jsonb then 'old'
              when md5(prompt) = '83efe3c343b9a73cbb8c6d9519c4ced2' and fields = '[{"key": "rw_arps", "tol": 5e-05, "unit": "ohm.m", "label": "Sample Rw at formation temperature (Arps)", "expected": 0.049910478128179045}, {"key": "rwe_ssp", "tol": 5e-05, "unit": "ohm.m", "label": "Rwe from the SP quicklook", "expected": 0.049831180824251246}, {"key": "sw_waterleg_mean", "tol": 0.0005, "unit": "v/v", "label": "Water-leg mean Sw with the Arps Rw", "expected": 0.9991043802143901}, {"key": "sand_a_net_arps", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the Arps Rw", "expected": 18}, {"key": "sand_a_sw_avg_arps", "tol": 0.005, "unit": "v/v", "label": "SAND_A pay-average Sw with the Arps Rw", "expected": 0.3609390898147585}, {"key": "sand_a_net_uncorrected", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the raw sample Rw", "expected": 16.5}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'petrophysics' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book petrophysics refused: petrophysics/advanced matches neither its published form (prompt md5 fc73fb0f8363d2b7cec10185793978da) nor its W1 form (prompt md5 83efe3c343b9a73cbb8c6d9519c4ced2), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book petrophysics: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book petrophysics refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Using the provided GR / RHOB / RT logs and the given parameters, compute Vsh (Larionov tertiary), density porosity, Archie water saturation and apply the cutoffs to report the net-pay summary for SAND_A (2010–2030 m) and SAND_B (2050–2080 m).',
           fields = '[{"key": "sand_a_net_m", "tol": 0.75, "unit": "m", "label": "SAND_A net pay", "expected": 18.0}, {"key": "sand_a_phi_avg", "tol": 0.01, "unit": "v/v", "label": "SAND_A average porosity", "expected": 0.20805198865869562}, {"key": "sand_a_sw_avg", "tol": 0.02, "unit": "v/v", "label": "SAND_A average Sw", "expected": 0.361262643786335}, {"key": "sand_b_net_m", "tol": 0.75, "unit": "m", "label": "SAND_B net pay", "expected": 5.5}, {"key": "sand_b_phi_avg", "tol": 0.01, "unit": "v/v", "label": "SAND_B average porosity", "expected": 0.1417010751338701}, {"key": "sand_b_sw_avg", "tol": 0.02, "unit": "v/v", "label": "SAND_B average Sw", "expected": 0.5423153983883204}]'::jsonb
     where app_slug = 'petrophysics' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book petrophysics refused: petrophysics/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '8b87ccc9c4917dec18964452eac31cc2' and fields = '[{"key": "sand_a_net_m", "tol": 0.75, "unit": "m", "label": "SAND_A net pay", "expected": 18.0}, {"key": "sand_a_phi_avg", "tol": 0.01, "unit": "v/v", "label": "SAND_A average porosity", "expected": 0.20805198865869562}, {"key": "sand_a_sw_avg", "tol": 0.02, "unit": "v/v", "label": "SAND_A average Sw", "expected": 0.361262643786335}, {"key": "sand_b_net_m", "tol": 0.75, "unit": "m", "label": "SAND_B net pay", "expected": 5.5}, {"key": "sand_b_phi_avg", "tol": 0.01, "unit": "v/v", "label": "SAND_B average porosity", "expected": 0.1417010751338701}, {"key": "sand_b_sw_avg", "tol": 0.02, "unit": "v/v", "label": "SAND_B average Sw", "expected": 0.5423153983883204}]'::jsonb) from public.academy_capstones where app_slug = 'petrophysics' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book petrophysics refused: petrophysics/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update moves it to a case of its own. Using the typewell parameters as given: compute neutron-density (average) and Wyllie sonic porosity, fit a Pickett line over 2072 to 2078 m, a window that starts three metres above the water leg, and evaluate Simandoux and Indonesia water saturation with linear Vsh. Report the SAND_A (2010 to 2030 m) zone means and the Pickett fit over 2072 to 2078 m.',
           fields = '[{"key": "phind_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean neutron-density porosity", "expected": 0.17615030026601647}, {"key": "phiw_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean Wyllie sonic porosity", "expected": 0.2069057569286416}, {"key": "pickett_a_rw_2072_2078", "tol": 0.002, "unit": "Ω·m", "label": "Pickett fit over 2072 to 2078 m: a·Rw", "expected": 0.6886854786769905}, {"key": "pickett_m_2072_2078", "tol": 0.0002, "unit": "-", "label": "Pickett fit over 2072 to 2078 m: cementation exponent m", "expected": 0.8784525453945112}, {"key": "sw_sim_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Simandoux)", "expected": 0.43350268917150697}, {"key": "sw_ind_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Indonesia)", "expected": 0.4280109754526606}]'::jsonb
     where app_slug = 'petrophysics' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book petrophysics refused: petrophysics/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '4fc93836432a158c77906d14bf752067' and fields = '[{"key": "phind_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean neutron-density porosity", "expected": 0.17615030026601647}, {"key": "phiw_avg_sand_a", "tol": 0.002, "unit": "v/v", "label": "SAND_A mean Wyllie sonic porosity", "expected": 0.2069057569286416}, {"key": "pickett_a_rw_2072_2078", "tol": 0.002, "unit": "Ω·m", "label": "Pickett fit over 2072 to 2078 m: a·Rw", "expected": 0.6886854786769905}, {"key": "pickett_m_2072_2078", "tol": 0.0002, "unit": "-", "label": "Pickett fit over 2072 to 2078 m: cementation exponent m", "expected": 0.8784525453945112}, {"key": "sw_sim_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Simandoux)", "expected": 0.43350268917150697}, {"key": "sw_ind_sand_a", "tol": 0.01, "unit": "v/v", "label": "SAND_A mean Sw (Indonesia)", "expected": 0.4280109754526606}]'::jsonb) from public.academy_capstones where app_slug = 'petrophysics' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book petrophysics refused: petrophysics/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. A lab measured the formation water sample at 0.114 ohm.m at 75 degF; formation temperature is 180 degF. The SP quicklook reads SSP = -93 mV with Rmfe = 0.62 ohm.m at formation temperature. Correct the sample with Arps, convert the SSP, and confirm both against the Pickett fit from the Professional tier. Then book SAND_A twice: with the corrected Rw and with the raw sample value, and watch what the wrong Rw does to pay.',
           fields = '[{"key": "rw_arps", "tol": 5e-05, "unit": "ohm.m", "label": "Sample Rw at formation temperature (Arps)", "expected": 0.049910478128179045}, {"key": "rwe_ssp", "tol": 5e-05, "unit": "ohm.m", "label": "Rwe from the SP quicklook", "expected": 0.049831180824251246}, {"key": "sw_waterleg_mean", "tol": 0.0005, "unit": "v/v", "label": "Water-leg mean Sw with the Arps Rw", "expected": 0.9991043802143901}, {"key": "sand_a_net_arps", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the Arps Rw", "expected": 18}, {"key": "sand_a_sw_avg_arps", "tol": 0.005, "unit": "v/v", "label": "SAND_A pay-average Sw with the Arps Rw", "expected": 0.3609390898147585}, {"key": "sand_a_net_uncorrected", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the raw sample Rw", "expected": 16.5}]'::jsonb
     where app_slug = 'petrophysics' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book petrophysics refused: petrophysics/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '83efe3c343b9a73cbb8c6d9519c4ced2' and fields = '[{"key": "rw_arps", "tol": 5e-05, "unit": "ohm.m", "label": "Sample Rw at formation temperature (Arps)", "expected": 0.049910478128179045}, {"key": "rwe_ssp", "tol": 5e-05, "unit": "ohm.m", "label": "Rwe from the SP quicklook", "expected": 0.049831180824251246}, {"key": "sw_waterleg_mean", "tol": 0.0005, "unit": "v/v", "label": "Water-leg mean Sw with the Arps Rw", "expected": 0.9991043802143901}, {"key": "sand_a_net_arps", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the Arps Rw", "expected": 18}, {"key": "sand_a_sw_avg_arps", "tol": 0.005, "unit": "v/v", "label": "SAND_A pay-average Sw with the Arps Rw", "expected": 0.3609390898147585}, {"key": "sand_a_net_uncorrected", "tol": 0.01, "unit": "m", "label": "SAND_A net pay with the raw sample Rw", "expected": 16.5}]'::jsonb) from public.academy_capstones where app_slug = 'petrophysics' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book petrophysics refused: petrophysics/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book petrophysics: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
